// Community index (public/community/mics.json, regenerated by the GitHub Action): fetched once, fails soft to null.
import { useEffect, useMemo, useState } from 'react'
import { COMMUNITY_INDEX_PATH, micKey, type CommunityIndex, type CommunityMicStats } from './types'

let cache: Promise<CommunityIndex | null> | null = null

/** Fetches the index once per page load; null when missing, unreachable or malformed. */
export function loadCommunityIndex(): Promise<CommunityIndex | null> {
  cache ??= fetch(`${import.meta.env.BASE_URL}${COMMUNITY_INDEX_PATH}`)
    .then((r) => (r.ok ? r.json() : null))
    .then((j: unknown) => {
      const idx = j as CommunityIndex | null
      return idx && idx.version === 1 && Array.isArray(idx.mics) ? idx : null
    })
    .catch(() => null)
  return cache
}

/** The community index once loaded (null while loading or when unavailable). */
export function useCommunityIndex(): CommunityIndex | null {
  const [idx, setIdx] = useState<CommunityIndex | null>(null)
  useEffect(() => {
    let alive = true
    void loadCommunityIndex().then((v) => alive && setIdx(v))
    return () => {
      alive = false
    }
  }, [])
  return idx
}

/** Community stats for this mic model (matched by micKey); null when the model is empty, unknown or has no reports. */
export function useCommunityMic(model: string): CommunityMicStats | null {
  const idx = useCommunityIndex()
  return useMemo(() => {
    const key = micKey(model)
    if (!idx || !key) return null
    const m = idx.mics.find((x) => x.key === key)
    return m && m.reports > 0 ? m : null
  }, [idx, model])
}
